WITH x AS (SELECT e.study_id, c.key AS camp, s.key AS strat, coalesce(s.value->>'date_start', e.period_start::date::string) AS d, max((s.value->>'spend')::float8) AS spend, max((s.value->>'impressions')::float8) AS imp FROM recruitment_data_events e, jsonb_each(e.data) AS c, jsonb_each(c.value) AS s WHERE jsonb_typeof(c.value)='object' AND jsonb_typeof(s.value)='object' AND s.value->>'spend' IS NOT NULL AND e.study_id IN (SELECT id FROM studies WHERE slug LIKE 'embed-%') GROUP BY 1,2,3,4)
SELECT st.slug, x.camp, count(DISTINCT x.strat) nstrat, count(DISTINCT x.d) days, min(x.d), max(x.d), round(sum(x.spend)::numeric,2), sum(x.imp) FROM x JOIN studies st ON st.id=x.study_id GROUP BY 1,2 ORDER BY 1,2;
